                                if ((if (@typeInfo(@TypeOf(prop)) == .@"enum") @intFromEnum(prop) else prop.value)) |v| {
                                    _ = &v;
                                    var expr = v;
                                    _ = &expr;
                                    _ = rewriteProperty(allocator, (&expr), edit);
                                }
                            }
                        }
                    }
                }
            }
        }
}

pub fn rewriteProperty(allocator: Allocator, object: *Expr, edit: *const PackageJsonEdit) void {
        if ((object.data != .e_object)) {
            return;
        }
        for (cp_mut_slice(&object.data.e_object.properties.slice())) |*prop| {
            _ = &prop;
            const key = (if ((prop.*).key) |k| ((k.asString(allocator)) orelse continue) else continue);
            if ((!std.mem.eql(u8, key, edit.key))) {
                continue;
            }
            const val = (if ((if (@typeInfo(@TypeOf((prop.*))) == .@"enum") @intFromEnum((prop.*)) else (prop.*).value)) |v| ((v.asString(allocator)) orelse continue) else continue);
            if ((!std.mem.eql(u8, strings.trim(val, strings.whitespace_chars), edit.old_literal))) {
                continue;
            }
            const copied = (blk_catch_2: { break :blk_catch_2 ((allocator.dupe(u8, edit.new_literal)) catch |__ce_2| { _ = &__ce_2; break :blk_catch_2 bun.outOfMemory(); }); });
            (if (@typeInfo(@TypeOf((prop.*))) == .@"enum") @intFromEnum((prop.*)) else (prop.*).value) = Expr.init(E.String, E.String{ .data = copied }, logger.Loc.Empty);
        }
}
